const listActionAttempts = `-- name: ListActionAttempts :many
SELECT id, action_run_id, attempt_number, phase, state, started_at, finished_at, error_code, error_detail, outcome_certainty, external_id, evidence_json FROM action_attempts
WHERE action_run_id = ?1 ORDER BY attempt_number
`

func (q *Queries) ListActionAttempts(ctx context.Context, actionRunID string) ([]*ActionAttempt, error) {
	rows, err := q.db.QueryContext(ctx, listActionAttempts, actionRunID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []*ActionAttempt{}
	for rows.Next() {
		var i ActionAttempt
		if err := rows.Scan(
			&i.ID,
			&i.ActionRunID,
			&i.AttemptNumber,
			&i.Phase,
			&i.State,
			&i.StartedAt,
			&i.FinishedAt,
			&i.ErrorCode,
			&i.ErrorDetail,
			&i.OutcomeCertainty,
			&i.ExternalID,
			&i.EvidenceJson,
		); err != nil {
			return nil, err
		}
		items = append(items, &i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

